    add("th2-list-4-10-example-of-hmmm-command-execution", "", "Handbook: Chapter 4: VDP and display screen (6)", "", "_List 4.10 Example of HMMM command execution_",
        R"MAN(LIVRO: MSX2 Technical Handbook (ASCII Corporation, 1987)
CAPITULO: Chapter 4: VDP and display screen (6)

    ;
    ;  List 4.10   HMMM sample
    ;                to use, set H, L, D, E, B, C and go
    ;                VRAM (H,L)-(D,E)  VRAM (B,C)
    ;                DIX must be set in D(bit 2)
    ;
    ;
    RDVDP:  EQU     0006H
    WRVDP:  EQU     0007H

    ;----- program start -----

    HMMM:   DI                              ;disable interrupt
            PUSH    BC                      ;save destination
            CALL    WAIT.VDP                ;wait end of command

            LD      A,(WRVDP)
            LD      C,A
            INC     C                       ;C := PORT#1's address
            LD      A,32
            OUT     (C),A
            LD      A,80H+17
            OUT     (C),A                   ;R#17 := 32

            INC     C
            INC     C                       ;C := PORT#3's address
            XOR     A
            OUT     (C),H                   ;SX
            OUT     (C),A
            OUT     (C),L                   ;SY
            OUT     (C),A

            LD      A,H                     ;make NX and DIX
            SUB     A
            LD      D,00000100B
            JP      NC,HMMM1
            LD      D,00000000B
            NEG
    HMMM1:  LD      H,A                     ;H := NX , D := DIX

            LD      A,L                     ;make NY and DIY
            SUB     A
            LD      E,00001000B
            JP      NC,HMMM2
            LD      E,00000000B
            NEG
    HMMM2:  LD      L,A                     ;L := NY , E := DIY

            LD      A,D
            OR      E
            POP     DE                      ;restore DX,DY
            PUSH    AF                      ;save DIX,DIY
            XOR     A
            OUT     (C),D                   ;DX
            OUT     (C),A
            OUT     (C),E                   ;DY
            OUT     (C),A
            OUT     (C),H                   ;NX
            OUT     (C),A
            OUT     (C),L                   ;NY
            OUT     (C),A
            OUT     (C),A                   ;dummy
            POP     AF
            OUT     (C),A                   ;DIX and DIY

            LD      A,11010000B             ;HMMM command
            OUT     (C),A

            EI
            RET

    GET.STATUS:
            PUSH    BC
            LD      BC,(WRVDP)
            INC     C
            OUT     (C),A
            LD      A,8FH
            OUT     (C),A
            LD      BC,(RDVDP)
            INC     C
            IN      A,(C)
            POP     BC
            RET

    WAIT.VDP:
            LD      A,2
            CALL    GET.STATUS
            AND     1
            JP      NZ,WAIT.VDP
            XOR     A
            CALL    GET.STATUS
            RET

            END

FONTE
  MSX2 Technical Handbook (ASCII Corporation, 1987); texto em ingles, como no original.)MAN");

