    add("th2-list-4-20-example-of-pset-command-execution", "", "Handbook: Chapter 4: VDP and display screen (6)", "", "_List 4.20 Example of PSET command execution_",
        R"MAN(LIVRO: MSX2 Technical Handbook (ASCII Corporation, 1987)
CAPITULO: Chapter 4: VDP and display screen (6)

    ;
    ;  List 4.20   PSET sample
    ;                to use, set H, L, E, A as follows
    ;                pset (x:H, y:L), color:E, logi-OP:A
    ;
    ;
            PUBLIC  PSET

    RDVDP:  EQU     0006H
    WRVDP:  EQU     0007H

    ;----- program start -----

    PSET:   DI
            PUSH    AF
            CALL    WAIT.VDP
            LD      BC,(WRVDP)

            INC     C
            LD      A,36
            OUT     (C),A
            LD      A,80H+17
            OUT     (C),A

            PUSH    BC
            INC     C
            INC     C
            XOR     A
            OUT     (C),H
            OUT     (C),A
            OUT     (C),L
            OUT     (C),A
            POP     BC

            LD      A,44
            OUT     (C),A
            LD      A,80H+17
            OUT     (C),A

            INC     C
            INC     C
            OUT     (C),E
            XOR     A
            OUT     (C),A

            LD      E,01010000B
            POP     AF
            OR      E
            OUT     (C),A

            EI
            RET

    GET.STATUS:
            PUSH    BC
            LD      BC,(WRVDP)
            INC     C
            OUT     (C),A
            LD      A,8FH
            OUT     (C),A
            LD      BC,(RDVDP)
            INC     C
            IN      A,(C)
            POP     BC
            RET

    WAIT.VDP:
            LD      A,2
            CALL    GET.STATUS
            AND     1
            JP      NZ,WAIT.VDP
            XOR     A
            CALL    GET.STATUS
            RET

            END

FONTE
  MSX2 Technical Handbook (ASCII Corporation, 1987); texto em ingles, como no original.)MAN");

